
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_b97_d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_b97_d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.523370789815970e+00, -4.432441513081260e+00, -4.305110928314986e+00, -4.128908965709190e+00, -3.889224517135246e+00, -3.571205259879006e+00, -3.164392149398901e+00, -2.671928933505502e+00, -2.126306354029255e+00, -1.602570302293614e+00, -1.127605227001661e+00, -7.686341260691355e-01, -6.559825170584360e-01, -5.395743415532520e-01, -3.889142772684684e-01, -2.435592742001039e-01, -1.691336966964571e-01, -9.050094969243890e-02, -2.283355204596921e-02, -2.735612305552443e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


